// actor/scripts/drive.ts — Person A's test harness against a running actor (local `terse actor dev` or the deployment).
// Run `terse actor generate` in actor/ first so ./generated exists. Usage: bun scripts/drive.ts [actorId]
import { PIER9 } from "../../shared/pier9.js"
import { ACTOR_ID, hhmm, type Offer, type Snapshot } from "../../shared/types.js"
// @ts-ignore generated by `terse actor generate`
import { actors } from "../generated/index.js"

const dock = actors.Dock.get(process.argv[2] ?? ACTOR_ID)
const show = (s: Snapshot) => {
  console.log(`\n== ${hhmm(s.simMin)} (${s.speed}x${s.frozen ? ", frozen" : ""}) moves=${s.counters.moves} side=$${s.counters.sidePaymentsUsd} avoided=$${s.counters.detentionAvoidedUsd}`)
  for (const d of s.doors) {
    const row = s.appts.filter(a => a.door === d.id && a.status !== "tomorrow").sort((a, b) => a.startMin - b.startMin)
      .map(a => `${hhmm(a.startMin)} ${a.truckId}${a.status === "booked" ? "" : ":" + a.status}`).join("  ")
    console.log(`door ${d.id} ${d.type.padEnd(6)} ${d.open ? "open  " : "CLOSED"} ${row}`)
  }
  console.log("timers:", s.timers.slice(0, 4).map(t => `${hhmm(t.atMin)} ${t.kind} ${t.truckId ?? t.auctionId ?? t.threadId ?? ""}`).join(" | "))
  console.log("open offers:", s.offers.filter((o: Offer) => o.status === "open").map(o => `${o.id} ${o.truckId}→door ${o.door} ${hhmm(o.startMin)} (${o.reason})`).join(" | ") || "none")
}

const step = async (title: string, fn: () => Promise<unknown>) => {
  console.log(`\n--- ${title}`)
  const r = await fn()
  console.log(JSON.stringify(r).slice(0, 400))
}

show(await dock.seed(PIER9))
await step("request door 4 14:00 for T13 (carrier-a)", () => dock.request("carrier-a", "T13", 4, 360))
await step("request door 4 14:00 for T14 (carrier-b): collision", () => dock.request("carrier-b", "T14", 4, 360))
await step("swap T14 <-> T13, pay $150", async () => [await dock.swap("T14", "T13"), await dock.pay("carrier-b", "carrier-a", 150)])
await step("arrive T3 (detention clock starts)", () => dock.arrive("T3"))
await step("reportEta T1 10:30", () => dock.reportEta("T1", 150))
await step("setDoor 5 closed", () => dock.setDoor(5, false))
show(await dock.snapshot())
const offers = (await dock.snapshot()).offers.filter((o: Offer) => o.status === "open" && o.truckId === "T5")
if (offers[0]) await step(`counter ${offers[0].id}: T5 wants door 6 10:00`, () => dock.counter(offers[0].id, 6, 120))
await step("say", () => dock.say("carrier-c", "carrier-b", "SWAP? @carrier-b — T5 takes door 6 10:00, we cover $150. Cold chain.", "o1"))
show(await dock.snapshot())
console.log("\nLeave this running and watch the dashboard: the 08:30 arrival check and the 10:30 detention alarm fire on their own.")
